nextflow_process {

    name "Test Process OPENMS_IDMASSACCURACY"
    script "../main.nf"
    process "OPENMS_IDMASSACCURACY"

    tag "modules"
    tag "modules_nfcore"
    tag "openms"
    tag "openms/idmassaccuracy"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('mzmls'), file('idxmls') ]
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated.") }
            )
        }
    }
}
